import { hash, verify } from '@denorg/scrypt'
// N=4096, r=8, p=1, 32-byte key; the salt is generated by the package.
const options = { logN: 12, r: 8, p: 1, dklen: 32 }
export const operation = ([password, wrong]) => {
  const stored = hash(password, options, 'phc')
  return [verify(password, stored), verify(wrong, stored)]
}
